# adminhub

Small user-admin service for our internal console. It keeps users in SQLite and exposes plain handler functions
(`adminhub/api.py`) that the web layer calls with the decoded request parameters and turns into HTTP responses.

## Handlers

| Handler | Parameters | Result |
| --- | --- | --- |
| `get_user` | `id` | 200 with the user, 404 if unknown |
| `list_users` | none | 200 with all users, ordered by id |
| `deactivate_user` | `id` | 200, 404 if unknown |
| `signups` | `start`, `end` (ISO dates, `end` exclusive) | 200 with signups per day |

Paged endpoints take `page` and `per_page`; **pages are numbered from 1**.

## Development

```
python -m pytest -q
```

All queries go through `sqlite3` with `?` placeholders. Pull requests are reviewed from the patch under `pr/`.
"""Request handlers. Each takes the connection and the decoded request parameters and returns a response dict."""

import sqlite3

from . import reports, users
from .errors import BadRequest, NotFound


def ok(body: dict) -> dict:
    return {"status": 200, "body": body}


def error(status: int, message: str) -> dict:
    return {"status": status, "body": {"error": message}}


def _user_id(params: dict) -> int:
    try:
        return int(params["id"])
    except (KeyError, ValueError):
        raise BadRequest("id must be an integer") from None


def get_user(conn: sqlite3.Connection, params: dict) -> dict:
    try:
        return ok(users.get_user(conn, _user_id(params)).to_dict())
    except NotFound as problem:
        return error(404, str(problem))
    except BadRequest as problem:
        return error(400, str(problem))


def list_users(conn: sqlite3.Connection, params: dict) -> dict:
    return ok({"users": [user.to_dict() for user in users.list_users(conn)]})


def deactivate_user(conn: sqlite3.Connection, params: dict) -> dict:
    try:
        users.deactivate_user(conn, _user_id(params))
    except NotFound as problem:
        return error(404, str(problem))
    except BadRequest as problem:
        return error(400, str(problem))
    return ok({"deactivated": 1})


def signups(conn: sqlite3.Connection, params: dict) -> dict:
    if "start" not in params or "end" not in params:
        return error(400, "start and end are required")
    return ok({"days": reports.signups_per_day(conn, params["start"], params["end"])})
"""Reading and changing users."""

import sqlite3
from datetime import datetime, timezone

from .errors import NotFound
from .models import User

SELECT_USER = "SELECT id, email, name, role, active, created_at FROM users"


def create_user(
    conn: sqlite3.Connection, email: str, name: str, role: str = "member", created_at: str | None = None
) -> User:
    """Insert a user and return it; `created_at` defaults to the current UTC time."""
    created_at = created_at or datetime.now(timezone.utc).isoformat(timespec="seconds")
    cursor = conn.execute(
        "INSERT INTO users (email, name, role, created_at) VALUES (?, ?, ?, ?)",
        (email, name, role, created_at),
    )
    conn.commit()
    return get_user(conn, cursor.lastrowid)


def get_user(conn: sqlite3.Connection, user_id: int) -> User:
    """Return one user or raise NotFound."""
    row = conn.execute(SELECT_USER + " WHERE id = ?", (user_id,)).fetchone()
    if row is None:
        raise NotFound(f"user {user_id} not found")
    return User.from_row(row)


def list_users(conn: sqlite3.Connection) -> list[User]:
    """All users, ordered by id."""
    rows = conn.execute(SELECT_USER + " ORDER BY id").fetchall()
